<?php require 'includes/header.php';
$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');
$s=$pdo->prepare("SELECT COUNT(*) n,COALESCE(SUM(total),0) total,COALESCE(SUM(amount_paid),0) paid,COALESCE(SUM(balance),0) balance FROM sales WHERE DATE(created_at) BETWEEN ? AND ?");$s->execute([$from,$to]);$sum=$s->fetch();
$exp=$pdo->prepare("SELECT COALESCE(SUM(amount),0) e FROM expenses WHERE DATE(created_at) BETWEEN ? AND ?");$exp->execute([$from,$to]);$expense=$exp->fetch()['e'];
$rows=$pdo->prepare("SELECT s.receipt_no,s.created_at,s.total,s.amount_paid,s.balance,s.payment_method,u.full_name FROM sales s JOIN users u ON u.id=s.user_id WHERE DATE(s.created_at) BETWEEN ? AND ? ORDER BY s.created_at DESC");$rows->execute([$from,$to]);$sales=$rows->fetchAll();
?><h1>Reports</h1><div class="panel"><form><div class="row"><input type="date" name="from" value="<?=$from?>"><input type="date" name="to" value="<?=$to?>"></div><button>Filter</button></form></div>
<div class="cards"><div class="card"><h3>Transactions</h3><div class="big"><?=$sum['n']?></div></div><div class="card"><h3>Sales</h3><div class="big">KSh <?=money($sum['total'])?></div></div><div class="card"><h3>Paid</h3><div class="big">KSh <?=money($sum['paid'])?></div></div><div class="card"><h3>Balances</h3><div class="big">KSh <?=money($sum['balance'])?></div></div><div class="card"><h3>Expenses</h3><div class="big">KSh <?=money($expense)?></div></div><div class="card"><h3>Sales - Expenses</h3><div class="big">KSh <?=money($sum['total']-$expense)?></div></div></div>
<div class="panel"><table><tr><th>Receipt</th><th>Date</th><th>Total</th><th>Paid</th><th>Balance</th><th>Method</th><th>Cashier</th></tr><?php foreach($sales as $r):?><tr><td><a href="receipt.php?id=<?=$r['receipt_no']?>"><?=e($r['receipt_no'])?></a></td><td><?=$r['created_at']?></td><td><?=money($r['total'])?></td><td><?=money($r['amount_paid'])?></td><td><?=money($r['balance'])?></td><td><?=e($r['payment_method'])?></td><td><?=e($r['full_name'])?></td></tr><?php endforeach;?></table></div><?php require 'includes/footer.php';?>